-- Generated by model/lib/sql/generate.mjs. The data's own members of each dimension, from dimensions/<Dimension>.csv in the folder of input cells,
-- numbered after the model's members. Parents first, so a member's parent ids exist when it goes in.

-- Brand Group
INSERT INTO "dim Brand Group" SELECT (SELECT coalesce(max("Brand Group"), 0) FROM "dim Brand Group") + row_number() OVER (ORDER BY c."Brand Group"), c."Brand Group"
FROM file('dimensions/Brand Group.csv', 'CSVWithNames', '"Brand Group" String') c 
WHERE c."Brand Group" NOT IN (SELECT name FROM "dim Brand Group");

-- Brand
INSERT INTO "dim Brand" SELECT (SELECT coalesce(max("Brand"), 0) FROM "dim Brand") + row_number() OVER (ORDER BY c."Brand"), c."Brand", coalesce(p0."Brand Group", throwIf(isNull(p0."Brand Group"), 'a member of Brand has a Brand Group the dimension does not have')), coalesce(p1."Brand Type", throwIf(isNull(p1."Brand Type"), 'a member of Brand has a Brand Type the dimension does not have'))
FROM file('dimensions/Brand.csv', 'CSVWithNames', '"Brand" String, "Brand Group" String, "Brand Type" String') c LEFT JOIN "dim Brand Group" p0 ON p0.name = if(c."Brand Group" = '', 'NULL (Brand Group)', c."Brand Group") LEFT JOIN "dim Brand Type" p1 ON p1.name = if(c."Brand Type" = '', 'NULL (Brand Type)', c."Brand Type")
WHERE c."Brand" NOT IN (SELECT name FROM "dim Brand");

